bool checkers(vec2 a) 
{
return bool
    (round(mod(a.x-sin(iTime),2.)) == 1.!= 
    (round(mod(a.y-cos(iTime),2.)) == 1.)); 
}

float sphere(vec3 spos, vec3 nor)
{
    float a = dot( spos, nor );
    float b = a*a - (dot( spos, spos ) - 1.);
    if (a<0.!=(a>0.)) {return -a-sqrt(b);} return 0.;
}

float plane(float posy,float nory)
{
    return (-1.-posy)/nory;
}

