void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (fragCoord*2.-iResolution.xy)/iResolution.y;
    vec3 nor = normalize(vec3(uv,1));
    //vec3 sur = vec3(0,0,0);
    vec3 pos = vec3(0,0.3,0);
    vec3 imouse = normalize(vec3((iMouse.xy*2.-iResolution.xy)/iResolution.y,1));
    if(iMouse.x==0.){imouse = normalize(vec3(0,-0.5,1));}
    float mp = plane(pos.y,imouse.y);
    vec3 spos = vec3(imouse*mp+pos)+vec3(0,1,0);
    int obj = 0;
    float dis = 0.;
    vec3 col = vec3(1);

    for(int i=0;i<=10;i++){
        if (nor.y>=0.)// awful ad-hoc solution for the intersection
        {dis = sphere(pos-spos,nor); if(dis>0.){obj = 1;}else{obj=0;}}
            else
            {
                if(obj==1)
                    {dis=plane(pos.y,nor.y);obj=2;} 
                else 
                    {dis = sphere(pos-spos,nor);
                if(plane(pos.y,nor.y)>abs(dis))
                    {obj=1;}
                else
                    {dis=plane(pos.y,nor.y);obj=2;}
            }
        }
        switch(obj)//object materials
        {
            case 0://sky
            {
            col*=vec3(-dot(nor,vec3(0,0.5,0))+1.);
            break;
            }

            case 1://sphere
            {
                col*=vec3(0.9);
                pos=nor*dis+pos;
                nor=reflect(nor,pos-spos);
                continue;
            }

            case 2://floor
            {
            if(int(checkers((nor*dis+pos).xz))==1)
                {
                col*=vec3(0.9,0.0,abs(cos(iTime)*0.9));
                }
            else
                {
                col*=vec3(abs(sin(iTime)*0.9),0.9,0.0);
                }
            pos=nor*dis+pos; nor=reflect(nor,vec3(0,1,0)); continue;
            }
            case 3:
            {

            }

        }
        break;
    }

    fragColor = vec4(sqrt(col),0.0);
}
